 dict(match=r"IndexError: list index out of range", title="That position does not exist", plain="You asked for a position the list does not have. Positions start at 0, so a list with 4 items only has positions 0 to 3. Asking for position 4 is too far.", fix="Check whether your loop or index goes one step past the end. The last position is len(list) - 1."),
 dict(match=r"IndexError: string index out of range", title="That position does not exist in the text", plain="You asked for a letter at a position the text does not have. Positions start at 0 and the last one is len(text) - 1.", fix="Check for an off-by-one: are you using len(text) where you need len(text) - 1."),
 dict(match=r"IndexError: pop from empty list", title="Nothing left to remove", plain="You tried to take an item out of a list that has no items.", fix="Check that the list has something in it before you remove from it."),
 dict(match=r"NameError: name '(.+)' is not defined", title="Python does not know that name", plain="You used the name {1}, but nothing has stored a value under that name yet. It may be a spelling difference, or you used it before the line that creates it.", fix="Check the spelling and capital letters of {1}, and make sure a line above gives it a value."),
 dict(match=r"^SyntaxError: invalid syntax$", title="Python cannot read this line", plain="The line is not written in a shape Python understands. Common causes: a missing colon at the end of an if, for or def line, a missing bracket or quote mark, or = used where == was meant.", fix="Look at the line named in the message and the line just above it. Count your brackets and quotes."),
 dict(match=r"SyntaxError: expected ':'", title="A colon is missing", plain="Lines that start with if, elif, else, for, while or def must end with a colon.", fix="Add : at the end of the line."),
 dict(match=r"SyntaxError: '\(' was never closed|SyntaxError: unterminated string literal|SyntaxError: EOL while scanning string literal", title="A bracket or quote mark was opened but not closed", plain="Every opening bracket or quote mark needs a matching closing one.", fix="Count the ( and ), and the quote marks, on the line named."),
 dict(match=r"SyntaxError: cannot assign to (.+) here\. Maybe you meant '==' instead of '='", title="You used = where you meant ==", plain="One = means store a value. Inside an if you want to ask a question, which takes two equals signs.", fix="Change = to == in the if line."),
 dict(match=r"SyntaxError: invalid syntax\. Maybe you meant '==' or ':=' instead of '='\?", title="You used = where you meant ==", plain="One = means store a value. Inside an if you want to ask a question, which takes two equals signs.", fix="Change = to == in the if line."),
 dict(match=r"IndentationError: expected an indented block", title="The lines under this line need to be indented", plain="After a line that ends with a colon, the lines that belong to it must be pushed in by 4 spaces.", fix="Indent the next line by 4 spaces."),
