 dict(match=r"TypeError: unsupported operand type\(s\) for (.+): '(\w+)' and '(\w+)'", title="Those two kinds of value do not mix", plain="You tried to use the operator {1} between a {2} and a {3}, and Python does not know how to do that.", fix="Check what each side holds. A common cause is input(), which gives text, not a number. Wrap it with int(...)."),
