# Concepts each lesson teaches. A problem may only use concepts taught in its own lesson or an earlier one.
# Names: print() style = built-in function, .split() style = method, the rest are plain words (see tools/concepts.py).
CONCEPTS = {
 "print": ["print()"],
 "variables": ["assign", "arith"],
 "equals": ["compare"],
 "remainder": ["mod", "floordiv"],
 "ifelse": ["if", "and", "or", "not"],
 "lists": ["list", ".append()", "sum()", "max()", "min()"],
 "indexing": ["index"],
 "slicing": ["slice"],
 "len": ["len()"],
 "range": ["range()", "list()"],
 "forloops": ["for", "augassign"],
 "functions": ["def", "return", "main_guard", "input()", "int()", ".split()", "map()"],
 "input": [],
 "strings": ["in", ".upper()", ".lower()"],
}
# Concepts that only appear in locked starter code (explained in "Reading the starter code").
STARTER_CONCEPTS = ["isinstance()", "starred", "listcomp", "tuple"]
for _l in LESSONS:
    _l["concepts"] = CONCEPTS[_l["id"]]
    if _l["id"] == "functions":
        _l["starter_concepts"] = STARTER_CONCEPTS
